class Solution {
    /** 169. Majority Element
     * https://leetcode.com/problems/majority-element/
     */
public:
    int majorityElement(vector<int>& nums) {
        const size_t m = nums.size() / 2;
        nth_element(nums.begin(), nums.begin() + m, nums.end());
        return nums[m];
    }
};

class Solution {
public:
    int majorityElement(vector<int>& nums) {
        const int m = nums.size() / 2;
        // nth_element(nums.begin(), nums.begin() + m, nums.end());
        auto partition = [](vector<int>& nums, int p, int r, const int& m) -> int {
            if (p == r) return p;
            const int pivot = nums[p];
            // /** "red book" implementation - return value optimized */
            for (int j = p + 1; j <= r;) {
                if (pivot > nums[j]) swap(nums[p++], nums[j++]);
                else if (pivot < nums[j]) swap(nums[r--], nums[j]);
                else ++j;
            }
            // for (int i = p; i <= r; ++i) { cout << nums[i] << ','; } cout << endl;
            if (m > r) return r;
            else if (m < p) return p;
            else return m;

            // /** hand crafted - timeout */
            // int j = p + 1;
            // do {
            //     if (nums[r] < nums[j]) swap(nums[r], nums[j]);
            //     if (pivot > nums[j]) {
            //         nums[p++] = nums[j];
            //         nums[j++] = pivot;
            //     } else {--r;}
            // } while (j <= r);
            // /** hand crafted - timeout */
            // for (int j = p + 1; j <= r;) {
            //     if (nums[r] < nums[j]) swap(nums[r], nums[j]);
            //     if (pivot > nums[j]) {
            //         nums[p++] = nums[j];
            //         nums[j++] = pivot;
            //     } else --r;
            // }

            // /** another hand crafted - better than "red book" vanila */
            // for (int j = r; j > p; --j) {
            //     if (pivot < nums[j]) swap(nums[r--], nums[j]);
            // }
            // swap(nums[r], nums[p]);

            // for (int i = p; i <= r; ++i) { cout << nums[i] << ','; } cout << endl;
            return r;
        };
        auto findQuick = [&partition](this auto&& self, vector<int>& nums, const int& j, const int& r, const int& m) {
            if (0 > m || m > r - j) return;
            int pos = partition(nums, j, r, m);
            if (m == pos) return;
            if (m > pos) self(nums, pos + 1, r, m);
            else self(nums, j, pos - 1, m);
        };
        findQuick(nums, 0, nums.size() - 1, m);
        return nums[m];
    }
};

